vertex.source:
#version 300 es

// Vertex info: input
in vec3 vertexPosition; // Vertex position in object space coordinates
in vec3 vertexNormal; // Surface normal at the vertex in object space coordinates
in vec2 vertexTextureCoordinates; // Texture coordinates at that vertex

// Coordinates info
uniform mat4 mMatrix; // Model matrix
uniform mat4 vMatrix; // View matrix
uniform mat4 pMatrix; // Projection matrix

// Light info
uniform vec4 lightPosition;
uniform bool lightInCamspace;

// Vertex info: output
out vec3 vertexNor;
out vec3 vertexPos;

// Light info: output
out vec3 lightPos;

// Main program for each vertex
void main() {
    // position of vertex
    gl_Position = pMatrix * vMatrix * mMatrix * vec4(vertexPosition, 1.0);

    // info of vertex
    vec4 vertexInCam = vMatrix * mMatrix * vec4(vertexPosition, 1.0);
    vertexNor = vec3(vMatrix * mMatrix * vec4(vertexNormal, 0.0));
    vertexPos = vec3(vertexInCam) / vertexInCam.w;

    // info of light
    if (lightInCamspace) lightPos = vec3(lightPosition);
    else lightPos = vec3(vMatrix * mMatrix * lightPosition);
}

fragment.source:
#version 300 es

// settings
precision highp float;

// Vertex info: input
in vec3 vertexPos;
in vec3 vertexNor;

// Light info: input
in vec3 lightPos;

// Material info
uniform vec4 color;
uniform vec4 ambient;
uniform vec4 diffuse;
uniform vec4 specular;
uniform float shininess;

// Vertex info: output
out vec4 fragColor;


// Main program for each fragment = pixel candidate
void main() {
    // global info
    vec3 vertex = vertexPos;
    vec3 normal = vertexNor;
    vec3 light = lightPos;

    // diffusion
    vec3 L = normalize(light - vertex);
    vec3 N = normalize(normal);
    float diffuse_coef = clamp(dot(L, N), 0., 1.);
    vec3 diffuse_color = vec3(color) * vec3(diffuse) * diffuse_coef;

    // specular
    vec3 R = normalize(2.0 * dot(N,L) * N - L);
    vec3 V = normalize(-1. * vertex);
    float specular_coef =  (shininess+2.) / (2. * 3.14) * pow(clamp(dot(R, V), 0., 1.), shininess);
    vec3 specular_color = vec3(specular) * specular_coef + diffuse_color * (1. - specular_coef);

    // ambient
    vec3 ambient_color = vec3(ambient) * vec3(color);

    // toon shader
    float I_f = dot(L,N);
    vec4 I;
    if (I_f > .98) I = vec4(.8, .8, .8, 1.);
    else if (I_f > .5) I = vec4(.8, .4, .4, 1.);
    else if (I_f > .24) I = vec4(.6, .2, .2, 1.);
    else I = vec4(.1, .1, .1, 1.);

    // color of vertex
    fragColor = vec4((diffuse_color + specular_color + ambient_color), color.a) * I;
}

vertex.source:
#version 300 es

// Vertex coordinates in object space for the render quad
in vec3 vertexPosition;
// Texture coordinate for this vertex and the render quad
in vec2 vertexTextureCoordinates;

// Texture coordinate needs to be passed on to the R2T fragment shader
out vec2 fragmentTextureCoordinates;

// Main program for each vertex of the render quad
void main() {
  gl_Position = vec4(vertexPosition, 1.0);
  fragmentTextureCoordinates = vertexTextureCoordinates;
}

fragment.source:
#version 300 es

precision highp float;

// A texture sampling unit, which is bound to the render quad texture buffer
uniform sampler2D textureRendered;

// Texture coordinates coming from the vertex shader, interpolated through the rasterizer
in vec2 fragmentTextureCoordinates;
out vec4 fragColor;

// Main program for each fragment of the render quad
void main() {
  fragColor = texture(textureRendered, fragmentTextureCoordinates.st);
}
